# factory-run state machine (template generated by software-factory).
#
# - FR-01: entry on an existing spec under specs/ whose status line is
#   exactly the ready status line of the profile's artefact -> Build phase;
#   otherwise Plan phase.
#   (The French forms of the status line are still accepted.)
# - FR-02: success if and only if verdict == APPROVED and tests_passed is true.
# - FR-03: at most 3 iterations; after the 3rd non-approved iteration, explicit
#   failure with the remaining issues. Never an approval by exhaustion.
# - FR-04: dead agent or unusable output -> one relaunch without consuming an
#   iteration, then explicit failure.
# - MD-07 (wiring): each agent has a model role (AGENT_ROLES); the
#   assignment resolved at start is kept in the state and logged.

from __future__ import annotations

from pathlib import Path
from typing import Any, Dict, Optional, Tuple

from . import counters, profiles, relaunch, specfile, verdicts

# PX-04: the roles, the agents and the ready status line come from the profile with a linear loop.
_PROFILE = profiles.by_machine("linear")
_AGENTS = profiles.loop_agents(_PROFILE)
PLANNER, BUILDER, VERIFIER = _AGENTS["plan"], _AGENTS["build"], _AGENTS["verify"]
AGENTS = (PLANNER, BUILDER, VERIFIER)
AGENT_ROLES = {r["name"]: r["model_role"] for r in _PROFILE["roles"]}
APPROVED_LINE = profiles.ready_status(_PROFILE)


class RunOver(RuntimeError):
    """Call after the end of the cycle (success or failure already returned)."""


def entry(arguments: str, root: Path) -> Dict[str, Any]:
    """FR-01 extended by BQ-07: picks the entry phase from $ARGUMENTS.

    - a ready spec -> build; a proposed spec -> approve (gate, then build);
    - a blocked spec -> approve once every blocking question is answered,
      otherwise mode "stop" (kind blocked) with the open questions;
    - a delivered spec -> mode "stop" (kind delivered);
    - a SPEC-*.md under specs/ with a missing or unknown status -> SpecError;
    - anything else is a free-text need: plan."""
    candidate = (arguments or "").strip().strip("'\"")
    if candidate:
        try:
            path = Path(candidate)
            full = path if path.is_absolute() else Path(root) / path
            rel = full.resolve().relative_to(Path(root).resolve())
            is_spec = (full.is_file() and rel.parts[:1] == ("specs",)
                       and rel.name.startswith("SPEC-") and rel.name.endswith(".md"))
        except (OSError, ValueError):
            # Free text (a need) that is not a valid path: Plan phase.
            is_spec = False
        if is_spec:
            parsed = specfile.parse(full.read_text(encoding="utf-8-sig", errors="replace"))
            mode, stop = specfile.entry_mode(parsed)
            result: Dict[str, Any] = {"mode": mode, "spec": rel.as_posix()}
            if stop == "blocked":
                result["questions"] = [{"id": q["id"], "text": q["text"]} for q in parsed["questions"]
                                       if q["id"] in parsed["unanswered"]]
            if stop:
                result["stop"] = stop
            return result
    return {"mode": "plan", "spec": None}


def new_state(models: Optional[Dict[str, str]] = None) -> Dict[str, Any]:
    return {
        "models": dict(models or {}),
        "iteration": 1,
        "max_iterations": counters.MAX_ITERATIONS,
        "failures": {},
        "status": "running",
        "issues": [],
        "expect": BUILDER,
    }


def record(state: Dict[str, Any], agent: str, output: Optional[str], dead: bool) -> Tuple[Dict[str, Any], Dict[str, Any]]:
    """Applies an agent's return. Returns (decision, journal fields)."""
    if state["status"] != "running":
        raise RunOver("cycle already finished: %s" % state["status"])
    if agent not in AGENTS:
        raise ValueError("unknown agent: %r" % (agent,))
    if agent == PLANNER and (state["iteration"] != 1 or state["expect"] != BUILDER):
        raise ValueError("the Planner only runs before the Build phase")
    if agent != PLANNER and agent != state["expect"]:
        raise ValueError("out-of-sequence call: expected %s, got %s" % (state["expect"], agent))
    iteration = 0 if agent == PLANNER else state["iteration"]
    parsed = None
    reason = "dead agent" if dead else None
    if not dead and agent == VERIFIER:
        try:
            parsed = verdicts.parse_verifier(output)
        except verdicts.UnusableOutput as exc:
            dead, reason = True, "unusable output: %s" % exc
    log = {"iteration": iteration, "verdict": "DEAD", "produced": 0}
    if dead:
        failures = state["failures"].get(agent, 0)
        decision = relaunch.on_dead(failures)
        state["failures"][agent] = failures + 1
        if decision == relaunch.RELAUNCH:
            return {"action": "relaunch", "agent": agent, "iteration": iteration, "reason": reason}, log
        state["status"] = "failed"
        return {
            "action": "fail",
            "agent": agent,
            "iteration": iteration,
            "reason": "%s died twice (%s): explicit failure, no verdict" % (agent, reason),
            "issues": state["issues"],
        }, log
    state["failures"][agent] = 0
    if agent == PLANNER:
        log["verdict"] = "DONE"
        return {"action": "plan-done", "iteration": 0}, log
    if agent == BUILDER:
        log["verdict"] = "DONE"
        state["expect"] = VERIFIER
        return {"action": "verify", "iteration": iteration}, log
    assert parsed is not None
    log["verdict"] = parsed["verdict"]
    log["produced"] = len(parsed["issues"])
    state["issues"] = parsed["issues"]
    if parsed["verdict"] == "APPROVED" and parsed["tests_passed"] is True:
        state["status"] = "success"
        return {"action": "success", "iteration": iteration, "tests_passed": True}, log
    if counters.cap_reached(iteration, state["max_iterations"]):
        state["status"] = "failed"
        return {
            "action": "fail",
            "iteration": iteration,
            "reason": "%d iterations without approval: explicit failure" % iteration,
            "issues": parsed["issues"],
        }, log
    state["iteration"] = iteration + 1
    state["expect"] = BUILDER
    return {
        "action": "fix",
        "iteration": iteration + 1,
        "tests_passed": parsed["tests_passed"],
        "issues": parsed["issues"],
    }, log
